package net.civeira.phylax.feature.identity.consentpurpose.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.feature.identity.consentpurpose.application.visibility.ConsentPurposeEntityEnrichment;
import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;

public class InheritTenantExcludingRoot {

  /**
   * @autogenerated FormulaPolicyGenerator
   * @param builder
   */
  public void calculate(@Observes ConsentPurposeEntityEnrichment builder) {
    Actor actor = builder.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      builder.peek(dto -> dto.tenant(TenantReference.of(actor.getTenant())));
    }
  }
}
